<?php declare(strict_types=1);namespace App\Controllers;use App\Core\{Controller,Security};use App\Models\User;use App\Services\AuthService;final class AuthController extends Controller{public function login():void{$this->view('auth.login',['title'=>'Login']);}public function register():void{$this->view('auth.register',['title'=>'Register']);}public function store():void{Security::verify();$name=$this->input('name');$email=filter_var($this->input('email'),FILTER_VALIDATE_EMAIL);$password=$this->input('password');if(!$name||!$email||strlen($password)<10){$this->view('auth.register',['title'=>'Register','error'=>'Enter a name, valid email, and password of at least 10 characters.']);return;}(new User($this->db))->create(['name'=>$name,'email'=>$email,'password'=>$password]);(new AuthService($this->db))->attempt((string)$email,$password);$this->redirect('/dashboard');}public function authenticate():void{Security::verify();if((new AuthService($this->db))->attempt($this->input('email'),$this->input('password')))$this->redirect('/dashboard');$this->view('auth.login',['title'=>'Login','error'=>'Invalid credentials.']);}public function logout():void{(new AuthService($this->db))->logout();$this->redirect('/');}public function forgot():void{$this->view('auth.forgot',['title'=>'Forgot Password']);}public function reset():void{$this->view('auth.reset',['title'=>'Reset Password']);}}
